/* Perimeter only. No fill keyword, no image painted across the middle. */
#top-bar::after,#send_form::after{
 content:"";position:absolute;inset:0;pointer-events:none;z-index:2;
 border:9px solid transparent;
 border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v4/bar-frame.webp') 22 45 / 9px 18px / 0 stretch;
}
